#!/usr/bin/env node
/**
 * Generates typed `as const` ABIs from the Foundry build output.
 *
 * Run `forge build` first, then `pnpm gen:abis`. Never edit the generated files
 * by hand: they are derived artifacts and the sync checks in CI rely on it.
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "../..");
const outDir = resolve(repoRoot, "out");
const targetDir = resolve(here, "../src/abis");

const targets = [
  { file: "DSCEngine.sol/DSCEngine.json", exportName: "dscEngineAbi", path: "../src/abis/dsc-engine.ts" },
  {
    file: "DecentralizedStableCoin.sol/DecentralizedStableCoin.json",
    exportName: "dscAbi",
    path: "../src/abis/dsc.ts",
  },
  {
    file: "AggregatorV3Interface.sol/AggregatorV3Interface.json",
    exportName: "aggregatorV3Abi",
    path: "../src/abis/aggregator-v3.ts",
  },
];

async function readArtifact(file) {
  const path = resolve(outDir, file);
  let raw;
  try {
    raw = await readFile(path, "utf8");
  } catch {
    throw new Error(
      `Missing artifact ${path}\n` +
        `Run \`forge build\` in the repository root before generating ABIs.`,
    );
  }
  const artifact = JSON.parse(raw);
  if (!Array.isArray(artifact.abi)) {
    throw new Error(`Artifact ${path} has no abi array`);
  }
  return artifact.abi;
}

const banner = `// AUTO-GENERATED by frontend/scripts/gen-abis.mjs — do not edit.\n// Source: Foundry \`out/\` artifacts, regenerated by \`pnpm gen:abis\`.\n`;

await mkdir(targetDir, { recursive: true });

for (const target of targets) {
  const abi = await readArtifact(target.file);
  const body = `${banner}\nexport const ${target.exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`;
  const outputPath = resolve(here, target.path);
  await writeFile(outputPath, body, "utf8");
  console.log(`wrote ${outputPath} (${abi.length} entries)`);
}
